# -*- coding: utf-8 -*-
# 单选题：PART 02 维生素平衡，出处：ycnc_paras.txt
q7 = [
# ---- 维生素平衡：极容易缺乏，很难过量 ----
{"q":"维生素在人体中的含量不到1%，它被称为“维持生命的元素”，原因是？","o":["如果没有维生素，人体内很多重要的生命活动都无法完成","它能提供大量能量","它构成身体主要结构","它能杀死病菌"],"a":0,"e":"维生素在人体中的含量很少，不到1%，但如果没有维生素，人体内很多重要的生命活动都无法完成，所以叫作维持生命的元素，简称“维生素”。"},
# ---- 我们太容易缺维生素了 ----
{"q":"脂溶性维生素包括？","o":["维生素A、D、E、K","维生素B族和维生素C","维生素A、B、C","维生素C和E"],"a":0,"e":"一类叫作脂溶性维生素，包括维生素A、D、E、K。这类维生素必须溶解在油脂里才能被吸收。"},
{"q":"脂溶性维生素的吸收特点是？","o":["必须溶解在油脂里才能被吸收","必须溶解在水里才能被吸收","直接经皮肤吸收","不需要介质"],"a":0,"e":"这类维生素必须溶解在油脂里才能被吸收。"},
{"q":"水溶性维生素包括？","o":["维生素B族和维生素C","维生素A和D","维生素E和K","维生素A、D、E、K"],"a":0,"e":"另一类叫作水溶性维生素，包括维生素B族和维生素C，水溶性维生素可溶解在水中，很容易流失。"},
{"q":"与大多数营养素不同，维生素的失衡特点是？","o":["从食物中获取的维生素一般不会过量，缺乏的情况居多","容易过量","既不过量也不缺乏","只能通过药物补充"],"a":0,"e":"但是维生素很特别，从食物中获取的维生素在人体内一般不会过量，缺乏的情况居多。"},
{"q":"维生素在人体内能否合成或相互转化？","o":["不能合成，也不能相互转化，只能从食物中获取","可以自行合成","可以相互转化","可由肠道细菌合成全部种类"],"a":0,"e":"维生素在人体内不能合成，也不能相互转化，只能从食物中获取，所以如果从食物中摄取不足，就会出现维生素缺乏的症状。"},
{"q":"水溶性维生素摄入多了会怎样？","o":["马上通过尿液和汗水从体内排出","在体内大量储存","转化为脂肪","引起中毒"],"a":0,"e":"尤其是水溶性维生素，特别容易流失，如果摄入多了，会马上通过尿液和汗水从体内排出。"},
{"q":"脂溶性维生素有“吃一顿，管三天”的特点，说明？","o":["能在人体的脂肪组织内储存，抗流失能力较强","必须每天补充","不能被吸收","没有营养作用"],"a":0,"e":"脂溶性维生素尽管能在人体的脂肪组织内储存，有“吃一顿，管三天”的特点，抗流失能力较强，但如果不良饮食习惯坚持几年、几十年不变，体内储存的维生素被消耗干净，当细胞缺乏维生素时就会出现许多疾病，甚至会导致死亡。"},
{"q":"维生素缺乏的诱因中，“膳食中供给不足”的典型例子是？","o":["生活条件太差，没有能力获得食物","偏食挑食","熬煮时间过长","长期吃快餐"],"a":0,"e":"日常生活中，维生素缺乏主要有以下几种诱因：第一，膳食中供给不足。比如生活条件太差，没有能力获得食物。"},
{"q":"食物加工过程中会造成维生素破坏丢失过多的做法不包括？","o":["熬煮时间过长","冲洗次数过多","油炸温度过高","冷藏保存"],"a":3,"e":"第二，食物加工过程中破坏丢失过多，如熬煮时间过长，冲洗次数过多，或者油炸温度过高，都会破坏食物中的维生素。"},
{"q":"那位周围神经炎患者每天吃白菜炖豆腐，炖多长时间？","o":["半小时","5分钟","1小时","2小时"],"a":0,"e":"我问她：“白菜豆腐您每次炖多长时间？”她的回答让我们诊室的人都吃了一惊：“半小时。”"},
{"q":"那位周围神经炎患者一周吃几个鸡蛋？","o":["一个","三个","七个","不吃"],"a":0,"e":"她说：“不是讲白菜豆腐保平安吗？我每天都吃白菜炖豆腐。不爱吃肉，一周吃一个鸡蛋。”"},
{"q":"作者指出，白面中？","o":["几乎不含维生素","富含维生素B族","富含维生素C","富含维生素A"],"a":0,"e":"有一些人会用白面做出各种食物，看似丰富，但是白面中几乎不含维生素，如果食物中不增加蔬菜、水果和肉类，也会出现身体亏空。"},
{"q":"补充脂溶性维生素制剂时要注意用量，原因是？","o":["不溶于水，难以从肾脏排出，易在身体里积存过多产生毒性作用","吸收太快","会随尿液排出","会破坏其他维生素"],"a":0,"e":"由于脂溶性维生素不溶于水，难以从肾脏排出，易在身体里积存过多产生毒性作用，所以我们在补充维生素A、D、E等脂溶性维生素制剂时要注意用量，别过犹不及。比如咱们给孩子吃鱼肝油的时候都要严格按照说明书吃。"},
{"q":"作者建议出租车司机在车上备的食物不包括？","o":["煮好的鸡蛋、牛肉干","洗干净的西红柿、黄瓜","奶片或红薯干","油炸薯片和含糖饮料"],"a":3,"e":"我坐出租车时经常和司机师傅聊天，建议他们可以在车上备一些煮好的鸡蛋、牛肉干，还有洗干净的西红柿、黄瓜，拿起来就能吃，另外再准备些奶片或红薯干当零食。"},
{"q":"下列会导致消化能力变差、影响维生素吸收的情况是？","o":["长期腹泻、胆汁分泌受限、胃酸分泌减少","长期运动","长期熬夜","长期补钙"],"a":0,"e":"例如，长期腹泻、胆汁分泌受限、胃酸分泌减少都会造成消化能力变差，影响维生素的吸收；如果膳食中脂肪含量低，也会影响脂溶性维生素的吸收。"},
{"q":"服用下列哪种药物会增加对维生素B6的需求？","o":["异烟肼、青霉胺及避孕药","阿司匹林","维生素C片","降压药"],"a":0,"e":"服用异烟肼、青霉胺及避孕药等也会增加对维生素B6 的需求。比如一些吃抗结核药的人容易出现四肢麻木的感觉，这是由于服药以后会影响维生素B族的代谢。"},
{"q":"维生素缺乏是一个渐进的过程，其发展顺序是？","o":["体内储备量降低→生化检查异常→组织病理变化→临床体征","先出现临床体征再有生化异常","直接出现组织病变","无规律可循"],"a":0,"e":"维生素缺乏是一个渐进的过程。开始时，体内储备量降低，身体会感觉到不适，但是各项检查尚且正常。当体内储备越来越低，生化检查开始出现异常，最后组织病理也发生变化，此时在临床上才会表现出相应体征，但这时已经晚了。"},
{"q":"患者出现症状或体征时，补充维生素的量应？","o":["远大于每日推荐量，因为要把身体中的亏空量算进去","等于每日推荐量","小于每日推荐量","随意即可"],"a":0,"e":"所以当我们看到患者出现症状或者体征时，补给的维生素含量要远大于每日推荐量，因为补进去的量要把身体中的亏空量算进去。"},
{"q":"关于维生素补充片，作者特别强调？","o":["最好选择从食物中提取的天然维生素，化学合成的不要长期摄入","合成维生素效果更好","可以随意长期大量服用","完全不能吃"],"a":0,"e":"经常吃一些维生素补充片也是很好的选择。但是在这里我要特别强调一下，维生素补充剂最好选择从食物中提取的天然维生素，化学合成的维生素不要长期摄入。"},
# ---- 维生素A ----
{"q":"近些年人体对维生素A的消耗比历史上任何年代都多，原因是？","o":["手机和电脑的广泛应用","食物种类减少","运动量增加","睡眠减少"],"a":0,"e":"近些年，由于手机和电脑的广泛应用，人体对维生素A的消耗比历史上任何年代都多。"},
{"q":"与维生素A关系更为密切的视觉状态是？","o":["黑暗中的视觉","明亮处的色觉","远距离视觉","动态视觉"],"a":0,"e":"因为视神经的光敏感作用需要维生素A，尤其是黑暗中的视觉状态与维生素A关系更为密切。"},
{"q":"维生素A缺乏最突出的症状是？","o":["暗适应能力下降，严重者在夜里会看不清东西","牙龈出血","口角炎","关节疼痛"],"a":0,"e":"维生素A缺乏最突出的症状是暗适应能力下降，严重者在夜里会看不清东西。"},
{"q":"把房屋的灯突然关掉，正常人应在多久内看见东西？","o":["10秒钟内","1分钟内","3分钟内","5分钟内"],"a":0,"e":"第二个方法是，把房屋的灯突然关掉，在黑暗中你过多久能看见东西。正常人10秒钟内应该可以看到。"},
{"q":"维生素A缺乏最常见的症状是？","o":["眼干燥症","夜盲以外的白内障","结膜炎以外的青光眼","近视"],"a":0,"e":"维生素A缺乏最常见的症状是眼干燥症：角膜、结膜上皮、泪腺等组织的修复过程非常需要维生素A的参与。"},
{"q":"维生素A严重缺乏导致的角膜损伤可能造成？","o":["不可逆转的失明","暂时视物模糊","色盲","散光"],"a":0,"e":"如果缺乏维生素A，会出现眼睛干涩、发炎，严重者会出现角膜软化、溃疡、角质化等一系列变化，角膜损伤严重常会导致不可逆转的失明。"},
{"q":"作者在地铁上观察到一些女性肩部、上肢、腿部皮肤角化干燥、呈小疙瘩状，他认为这是？","o":["维生素A缺乏的表现","皮肤过敏","缺乏维生素C","真菌感染"],"a":0,"e":"我坐地铁时，常常发现一些女性，尽管脸上抹了化妆品，但是肩部、上肢、腿部的皮肤角化干燥，呈小疙瘩状，这都是维生素A缺乏的表现。"},
{"q":"口腔、呼吸道很干或者慢性咽炎，往往与缺乏什么有关？","o":["维生素A","维生素C","维生素D","钙"],"a":0,"e":"另外，口腔、呼吸道很干或者慢性咽炎，也往往与维生素A缺乏有关。"},
{"q":"家里孩子经常出现支气管肺炎，父母应首先考虑？","o":["孩子日常是否缺维生素A","孩子是否缺钙","孩子是否缺铁","孩子是否缺锌"],"a":0,"e":"家里如果有经常出现支气管肺炎的孩子，父母一定要好好想想，孩子日常生活中是不是缺维生素A了。"},
{"q":"可以直接获得维生素A的动物性食物是？","o":["动物肝脏、奶油和鸡蛋","瘦肉和鱼","牛奶和酸奶","骨头汤"],"a":0,"e":"第一，从动物肝脏、奶油和鸡蛋中直接获得维生素A。"},
{"q":"为了吸收植物中的胡萝卜素，作者建议的做法是？","o":["制造一个油性的环境，如吃胡萝卜炖牛腩、猪肉炖南瓜、炒西蓝花","生吃胡萝卜","水煮胡萝卜","榨汁饮用"],"a":0,"e":"第二，制造一个油性的环境，把植物中的胡萝卜素溶进去，比如吃胡萝卜炖牛腩、猪肉炖南瓜、炒西蓝花、炒油菜、炒菠菜等来吸收维生素A。"},
{"q":"一个胡萝卜素分子可以转化为几个维生素A分子？","o":["两个","一个","三个","四个"],"a":0,"e":"肠道黏膜可以根据身体中对维生素A的需求量来决定对胡萝卜素的吸收量。一个胡萝卜素分子可以转化为两个维生素A分子，身体缺维生素A时肠道对胡萝卜素转化吸收的就多，够了就减少吸收，这样就不会出现体内维生素A中毒问题。"},
{"q":"肠道黏膜对胡萝卜素的吸收机制说明？","o":["身体缺维生素A时吸收转化多，够了就减少吸收，不会中毒","吸收是无限量的","完全不吸收","只能被动吸收"],"a":0,"e":"身体缺维生素A时肠道对胡萝卜素转化吸收的就多，够了就减少吸收，这样就不会出现体内维生素A中毒问题。"},
# ---- 维生素D ----
{"q":"近年来对维生素D的研究已把它上升到什么的高度？","o":["激素","维生素","矿物质","蛋白质"],"a":0,"e":"近年来对维生素D的研究越来越多，现在已经把它上升到激素的高度。研究发现，维生素D不仅与骨骼有关，还与细胞功能的调节及基因转录相关。"},
{"q":"维生素D除了与骨骼有关，还与什么相关？","o":["细胞功能的调节及基因转录","血液凝固","肌肉收缩的唯一能量来源","胃肠蠕动"],"a":0,"e":"研究发现，维生素D不仅与骨骼有关，还与细胞功能的调节及基因转录相关。"},
{"q":"关于维生素D受体的分布，正确的说法是？","o":["遍布全身，包括大脑细胞都会受到维生素D的影响","只分布在骨骼","只分布在肾脏","只分布在皮肤"],"a":0,"e":"维生素D的受体遍布全身，因此全身各处包括大脑细胞都会受到维生素D的影响。"},
{"q":"维生素D缺乏在不同人群中的分布有什么特点？","o":["城市人多于农村人，女性多于男性，冬天和春天最为高发","农村人多于城市人","男性多于女性","夏天最为高发"],"a":0,"e":"维生素D缺乏现在已经成为非常广泛而严重的健康问题，患者中居住在城市里的人多于农村人，女性多于男性，冬天和春天最为高发。"},
{"q":"缺乏维生素D的表现形式不包括？","o":["骨质疏松、小儿盗汗等缺钙表现","容易过敏，容易感冒","好发肿瘤、抑郁","牙龈出血"],"a":3,"e":"缺乏维生素D的表现形式有：骨质疏松、小儿盗汗等缺钙表现，容易过敏，容易感冒，好发肿瘤、抑郁等。此外，冠心病、高血压、糖尿病等也与维生素D缺乏有关。"},
{"q":"下列疾病中，与维生素D缺乏有关的是？","o":["冠心病、高血压、糖尿病","坏血病","脚气病","夜盲症"],"a":0,"e":"此外，冠心病、高血压、糖尿病等也与维生素D缺乏有关。因此患这些疾病的患者在检查时也应该查一下自己血液里维生素D的浓度。"},
{"q":"含维生素D的动物类食物不包括？","o":["动物的肝脏、大脑、肺、脾","鸡蛋、牛奶","三文鱼、大马哈鱼","精米、精面"],"a":3,"e":"含维生素D的食物有：动物的肝脏、大脑、肺、脾，鸡蛋，牛奶，三文鱼，大马哈鱼，动物的骨头和皮肤也含有少量维生素D。"},
{"q":"人体皮肤合成维生素D的原料是？","o":["7-脱氢胆固醇","胡萝卜素","麦角固醇","胆固醇酯"],"a":0,"e":"人体的表皮与真皮内含有一定量的7-脱氢胆固醇，当受到阳光或紫外光照射时，可以经光化学反应形成前维生素D3，再经过肝脏和肾脏的羟化作用，最后转化为有活性的维生素D3 。"},
{"q":"皮肤合成的维生素D3需要经过哪些器官的羟化作用才有活性？","o":["肝脏和肾脏","心脏和肺","胃和肠","脾和胰腺"],"a":0,"e":"当受到阳光或紫外光照射时，可以经光化学反应形成前维生素D3，再经过肝脏和肾脏的羟化作用，最后转化为有活性的维生素D3 。"},
{"q":"作者说“我们的老祖宗都不缺维生素D”，原因是？","o":["食物中不缺乏肉类，在外面打猎时又能获得充足的阳光","他们服用补充剂","他们基因不同","他们不晒太阳"],"a":0,"e":"我们的老祖宗都不缺维生素D，因为他们的食物中不缺乏肉类，在外面打猎时又能获得充足的阳光。"},
{"q":"国际上有超过2500篇研究证实，维生素D能够将乳腺癌、前列腺癌和结肠癌的风险减少？","o":["50%","30%","20%","73%"],"a":0,"e":"国际上有超过2500篇公开发表成果的研究证实维生素D在预防癌症中有重要作用。无论是来自阳光照射自我合成的内源性维生素D，还是由营养补充方式获得的维生素D，都能够阻止身体内部癌症的发生，将乳腺癌、前列腺癌和结肠癌的风险减少50%，还能减少痴呆和神经系统失调的风险。"},
{"q":"人体获取维生素D的最佳途径是什么？","o":["日晒","口服补充剂","吃钙片","喝牛奶"],"a":0,"e":"既然维生素D如此重要，那么获取维生素D的最好方式是什么呢？是日晒。我们每天要花半个小时接触阳光，哪怕是在背阴的地方接受散射的太阳光线也好。"},
{"q":"为补充维生素D，每天要花多长时间接触阳光？","o":["半个小时","两个小时","五分钟","三个小时"],"a":0,"e":"我们每天要花半个小时接触阳光，哪怕是在背阴的地方接受散射的太阳光线也好。"},
{"q":"作者建议将血液中的维生素D保持在什么范围？","o":["40～60纳克/毫升","10～20纳克/毫升","100～200纳克/毫升","80～100纳克/毫升"],"a":0,"e":"较少外出的人需要补充一些维生素D，可以通过吃前文提到的动物类食物来补充，以将血液中的维生素D保持在40～60纳克／毫升。"},
# ---- 维生素B族 ----
{"q":"维生素B族被世界公认的有几种？","o":["9种","12种","5种","20种"],"a":0,"e":"维生素B族是个大家庭，成员有12种以上，被世界公认的有9种，全部是水溶性维生素，包括维生素B1 、维生素B2 、维生素B6 、维生素B12、烟酸、叶酸、泛酸、生物素和胆碱。"},
{"q":"维生素B族全部属于？","o":["水溶性维生素","脂溶性维生素","矿物质","必需脂肪酸"],"a":0,"e":"维生素B族是个大家庭，成员有12种以上，被世界公认的有9种，全部是水溶性维生素。"},
{"q":"B族维生素在三大能量代谢中的角色类似于？","o":["助燃剂","燃料","润滑剂","阻燃剂"],"a":0,"e":"第一，合成辅酶，参与三大能量代谢。B族维生素的角色类似于助燃剂，如果B族缺乏，辅酶的活性会降低，人的新陈代谢速度就会减慢。"},
{"q":"神经系统的功能完善与哪类维生素关系最密切？","o":["维生素B1、B6、B12","维生素A、D、E","维生素C","维生素K"],"a":0,"e":"第二，完善神经细胞功能，尤其是维生素B1 、维生素B6 、维生素B12与神经系统的功能完善密切相关。"},
{"q":"参与细胞DNA构成、促进细胞分裂的维生素是？","o":["叶酸","维生素B1","维生素C","维生素D"],"a":0,"e":"第三，促进细胞分裂。我们熟悉的叶酸，参与细胞DNA的构成。"},
{"q":"维生素B族缺乏时最常见的表现是什么？","o":["上火，表现为眼结膜充血、烦躁、口腔溃疡","皮肤干燥","牙龈出血","骨痛"],"a":0,"e":"维生素B族是个大家族，往往一种维生素缺乏时，其他种类维生素也缺乏。缺乏维生素B族最常见的症状是上火，表现为眼结膜充血，烦躁，口腔溃疡。"},
{"q":"熬夜加班后容易出现“上火”症状，原因是？","o":["加班熬夜时要消耗大量能量，脑细胞快速运转，消耗大量维生素B族","熬夜导致缺水","熬夜导致免疫力下降","熬夜使体温升高"],"a":0,"e":"熬夜加班之后也容易出现类似症状，为什么？因为在加班熬夜时要消耗大量能量，脑细胞快速运转，在这个过程中要消耗大量维生素B族。"},
{"q":"感冒之后人们常说“上火了”，作者解释是因为？","o":["免疫系统与病毒作战加快三大能量代谢，维生素B族作为辅酶被大量消耗","病毒直接破坏口腔黏膜","发热导致脱水","药物副作用"],"a":0,"e":"感冒也是同样的道理。感冒之后，许多人都说自己上火了，这是由于免疫系统在与病毒作战的过程中要加快碳水化合物、蛋白质、脂类这三大能量的代谢，而维生素B族作为三大能量代谢的辅酶，会大量被消耗。"},
{"q":"缺乏维生素B族最容易表现出的症状是？","o":["神经系统症状，如记忆力下降、反应迟钝、头痛","皮肤症状","消化系统症状","骨骼症状"],"a":0,"e":"缺乏维生素B族最容易表现出神经系统症状：人会出现记忆力下降，反应迟钝，没有精神，容易头痛，严重者会出现眩晕，感觉到头晕目眩，躺在床上不敢翻身，稍微一动就会呕吐。"},
{"q":"反复头痛、做CT和核磁都是阴性的人，作者认为可能是？","o":["体内维生素B不平衡","脑供血不足","脑肿瘤早期","偏头痛"],"a":0,"e":"还有一些人由于反复头痛，跑去做CT和核磁，结果都是阴性，其实就是体内维生素B不平衡了。"},
{"q":"维生素B族最突出的问题是周围神经症状，表现为？","o":["四肢和手脚有套袜套样的感觉障碍，手脚是木的","剧烈疼痛","皮肤瘙痒","关节肿胀"],"a":0,"e":"最突出的问题是周围神经症状：当维生素B1 、维生素B6 、维生素B12缺乏时，人会出现四肢和手脚套袜套样的感觉障碍，手脚是木的。"},
{"q":"B族维生素不足时，还容易出现？","o":["食欲不振、消化不良，甚至口臭","多食易饥","便秘为主","血压升高"],"a":0,"e":"B族维生素不足时，患者还容易出现食欲不振，消化不良，甚至一些人会出现口臭，别人都不敢靠近他。"},
{"q":"那位口臭患者的饮食特点是？","o":["每天吃馒头、米饭和面条，爱吃涮羊肉，喜欢辣椒和咸菜，蔬菜水果基本上一点都不吃","爱吃蔬菜水果","每天喝牛奶","严格素食"],"a":0,"e":"他说：“每天吃馒头、米饭和面条，爱吃涮羊肉，喜欢吃点辣椒和咸菜，蔬菜和水果基本上一点都不吃。”"},
{"q":"维生素B1主要存在于？","o":["种子皮、动物内脏和瘦肉","奶类和蛋类","绿叶蔬菜","水果"],"a":0,"e":"维生素B1 ——种子皮、动物内脏和瘦肉。"},
{"q":"维生素B2的食物来源是？","o":["动物肝脏、奶类、蛋类、豆类和绿叶蔬菜","种子皮和瘦肉","水果和坚果","海产品"],"a":0,"e":"维生素B2 ——动物肝脏、奶类、蛋类、豆类和绿叶蔬菜。"},
{"q":"维生素B12的食物来源是？","o":["动物肝脏、肉类、蛋类和奶类","绿叶蔬菜","水果和坚果","种子皮"],"a":0,"e":"维生素B12 ——动物肝脏、肉类、蛋类和奶类。"},
{"q":"叶酸的食物来源是？","o":["动物肝脏、肾脏、蛋类、豆类、绿叶蔬菜、水果和坚果类","只有绿叶蔬菜","只有动物内脏","只有水果"],"a":0,"e":"叶酸——动物肝脏、肾脏、蛋类、豆类、绿叶蔬菜、水果和坚果类。"},
{"q":"作者说“营养师们都特别喜欢动物肝脏”，因为？","o":["动物肝脏简直就是维生素大库房","肝脏价格便宜","肝脏容易烹饪","肝脏含能量高"],"a":0,"e":"大家发现没有，动物肝脏简直就是维生素大库房，所以营养师们都特别喜欢动物肝脏。"},
{"q":"关于肝脏是“解毒器官”，作者的解释是？","o":["肝脏是排毒器官，不是存毒器官","肝脏确实会储存毒素","肝脏毒素无法排出","肝脏毒素需要药物清除"],"a":0,"e":"但是大家经常困惑，肝脏是解毒器官，是不是里面有许多毒素呀？实际上这是个天大的误区，肝脏是排毒器官，不是存毒器官。"},
{"q":"B族维生素在体内的滞留时间只有？","o":["数小时","数天","数周","数月"],"a":0,"e":"第一，B族维生素属于水溶性维生素，很容易丢失，在体内的滞留时间只有数小时，所以必须每日补充，尤其是夏天和出汗多的时候。"},
{"q":"作者用“球队”比喻B族维生素，强调？","o":["不要单独补一种，各种B族维生素要一起补","只补一种即可","球员之间互相竞争","越贵越好"],"a":0,"e":"第二，B族维生素像个球队，球员之间相互配合才能取得胜利，也就是说不要单独补一种，比如一些人口腔溃疡，明显是缺乏维生素B2 ，但如果只是补了维生素B2 ，很快症状又会复发。如果把各种B族维生素一起补，好得快，还不容易复发。"},
{"q":"维生素B1、B2、B6之间的优质配比是？","o":["1∶1∶1","1∶2∶3","2∶1∶1","3∶2∶1"],"a":0,"e":"第三，维生素B1 、维生素B2 、维生素B6 之间的优质配比是1∶1∶1。"},
# ---- 维生素C ----
{"q":"维生素C在体内的作用不包括？","o":["皮下、血液中、细胞内外起抗氧化作用","参与胶原蛋白的形成","参与肾上腺皮质激素的合成与释放","储存能量"],"a":3,"e":"维生素C在皮下、血液中、细胞内外都起着抗氧化的作用，参与胶原蛋白的形成。此外，肾上腺皮质激素的合成与释放也需维生素C参与。维生素C能促进抗体形成，增加抵抗力。"},
{"q":"缺乏维生素C时，胶原蛋白形成障碍，会造成？","o":["创伤愈合延缓和不同程度的出血","骨骼变形","神经损伤","肌肉萎缩"],"a":0,"e":"当缺乏维生素C时，胶原蛋白形成障碍，会造成创伤愈合延缓和不同程度的出血。"},
{"q":"体内有铅、苯、砷及某些药物和细菌毒素蓄积时，给予大量什么可缓解其毒性？","o":["维生素C","维生素A","维生素D","维生素E"],"a":0,"e":"如果体内的毒物如铅、苯、砷及某些药物和细菌、毒素蓄积，给予大量的维生素C可缓解其毒性。"},
{"q":"维生素C缺乏症又称为？","o":["坏血病","脚气病","癞皮病","夜盲症"],"a":0,"e":"维生素C缺乏症又称为坏血病。"},
{"q":"坏血病的早期症状不包括？","o":["倦怠、疲乏、急躁","呼吸急促","牙龈疼痛出血、伤口愈合不良","骨质疏松"],"a":3,"e":"维生素C缺乏症又称为坏血病，早期症状是倦怠、疲乏、急躁、呼吸急促、牙龈疼痛出血、伤口愈合不良、关节肌肉短暂性疼痛、易骨折等。"},
{"q":"坏血病的典型症状是？","o":["牙龈肿胀出血、牙床溃烂、牙齿松动、毛细血管脆性增加","皮肤干燥脱屑","骨头和关节疼痛","夜盲"],"a":0,"e":"典型症状是牙龈肿胀出血、牙床溃烂、牙齿松动、毛细血管脆性增加。严重者可导致皮下、肌肉和关节出血及血肿形成，最终出现贫血，心脏衰竭，直至死亡。"},
{"q":"坏血病严重时最终可能导致？","o":["贫血，心脏衰竭，直至死亡","失明","瘫痪","痴呆"],"a":0,"e":"严重者可导致皮下、肌肉和关节出血及血肿形成，最终出现贫血，心脏衰竭，直至死亡。"},
{"q":"有些患者说吃一点阿司匹林就皮下出血，作者一问平时如何吃水果，回答是？","o":["“血糖高，哪敢吃呀”或“老了，咬不动”","“每天吃三种”","“不爱吃甜食”","“只吃进口水果”"],"a":0,"e":"我一问平时如何吃水果，回答都差不多：“血糖高，哪敢吃呀。”要不就说：“老了，咬不动。”"},
{"q":"对不吃水果的患者，作者的建议是？","o":["不能因噎废食，咬不动可以榨汁喝，怕血糖高还有血糖高的吃法","尊重习惯，不吃就不吃","改吃维生素片即可","用蔬菜完全替代水果"],"a":0,"e":"每次我都会和患者说，不能因噎废食，不吃水果哪儿来的维生素？咬不动可以榨汁喝，怕血糖高，还有血糖高的吃法。"},
{"q":"维生素C主要来源于？","o":["新鲜蔬菜与水果","动物肝脏","奶类和蛋类","谷物和豆类"],"a":0,"e":"维生素C主要来源于新鲜蔬菜与水果，如韭菜、菠菜、柿子椒等深色蔬菜和花椰菜，以及柑橘、山楂、柚子等水果。"},
{"q":"下列维生素C含量尤其丰富的野生食物是？","o":["苋菜、刺梨、沙棘、猕猴桃、酸枣","苹果、梨","香蕉、西瓜","白菜、萝卜"],"a":0,"e":"野生的苋菜、刺梨、沙棘、猕猴桃、酸枣等维生素C含量尤其丰富。"},
{"q":"中国人维生素C的主要来源为什么是水果？","o":["中国人蔬菜基本上炒熟了吃，而维生素C怕热，会损失很多","中国人不吃蔬菜","水果比蔬菜便宜","水果维生素C含量更高"],"a":0,"e":"需要说明的是，中国人的饮食习惯中，蔬菜基本上是炒熟了吃，但维生素C怕热，这样会损失很多维生素C。因此水果就成了中国人维生素C的主要来源了。"},
{"q":"作者建议一个人一天最好吃几种水果、共多少？","o":["3种以上，合起来半斤以上","1种，半斤","5种，一斤","2种，二两"],"a":0,"e":"一个人一天最好吃3种以上水果，合起来半斤以上。当然如果服用天然的维生素C片也是一个很好的补充方法。"},
# ---- 维生素平衡小结 ----
{"q":"作者对化学合成维生素的评价是？","o":["还远达不到天然维生素的效果","效果优于天然维生素","与天然维生素完全相同","可以完全替代天然维生素"],"a":0,"e":"每一种维生素的缺乏都会给身体健康带来严重的营养问题，而化学合成的维生素还远达不到天然维生素的效果。"},
{"q":"补充维生素的正确态度是？","o":["对症下药、量体裁衣，根据自己的症状判断所缺种类","多多益善","统一补充复合维生素即可","只补维生素C"],"a":0,"e":"补充维生素我们要对症下药、量体裁衣，根据自己的症状，判断自己所缺的维生素种类，然后吃相对应的肉类、果蔬。"},
{"q":"关于两类维生素的摄入风险，作者总结为？","o":["水溶性的不怕摄入过多，就怕不够；脂溶性的如果摄入过多，就会导致中毒","两类都怕过多","两类都怕不够","脂溶性不怕过多"],"a":0,"e":"不过，要时刻强调的一点就是，维生素有两类，即脂溶性的和水溶性的。水溶性的不怕摄入过多，就怕不够；脂溶性的如果摄入过多，就会导致中毒。"},
{"q":"血液中的维生素D应保持在什么范围？","o":["40～60纳克／毫升","10～20纳克／毫升","100～200纳克／毫升","越高越好"],"a":0,"e":"较少外出的人需要补充一些维生素D，可以通过吃前文提到的动物类食物来补充，以将血液中的维生素D保持在40～60纳克／毫升。"},
]
